: >/tmp/paper-observers.pid; for c in 0 1; do taskset $((1 << c)) sh -c 'c=$1; b=$(cat /proc/sys/kernel/random/boot_id); echo paper-affinity $c $$ $(grep Cpus_allowed_list /proc/self/status); while :; do u=$(cut -d" " -f1 /proc/uptime); v=$(dd if=/dev/mem bs=4 skip=29360128 count=1 2>/dev/null | od -An -tx4 | tr -d " \n"); h=$(dd if=/dev/mem bs=4096 skip=28672 count=1 2>/dev/null | md5sum | cut -d" " -f1); printf "paper-vcpu %s %s %s %s %s\n" "$c" "$u" "$b" "$v" "$h"; sleep 1; done' sh "$c" >>/dev/ttyS0 2>&1 & echo $! >>/tmp/paper-observers.pid; done
